#!/usr/bin/env sh
set -eu
RUN="${YUZHOU_MIGRATION_RUN_ID:-}";DB="${YUZHOU_TARGET_DATABASE:-}";PG="${YUZHOU_POSTGRES_CONTAINER:-jinhu-smart-park-postgres}";EXPECTED_PROJECT="${YUZHOU_EXPECTED_POSTGRES_COMPOSE_PROJECT:-jinhu_hr_migration_lab}";[ "${ALLOW_YUZHOU_MIGRATION:-no}" = yes ]||exit 2;[ "${ALLOW_YUZHOU_ROLLBACK:-no}" = yes ]||exit 2;printf %s "$DB"|grep -Eq '^jinhu_hr_migration_lab_'||exit 2;[ "$(docker inspect --format '{{index .Config.Labels "com.docker.compose.project"}}' "$PG" 2>/dev/null||true)" = "$EXPECTED_PROJECT" ]||exit 2
docker exec -i "$PG" psql -X -v ON_ERROR_STOP=1 -U jinhu -d "$DB" -v run="$RUN" <<'SQL'
BEGIN;SELECT set_config('yz.run',:'run',true);DO $$BEGIN IF NOT EXISTS(SELECT 1 FROM migration_batch WHERE run_id=current_setting('yz.run') AND status='succeeded')THEN RAISE EXCEPTION 'succeeded batch not found';END IF;END$$;DELETE FROM hr_contract_reminder_outbox o USING hr_contract_reminder r,legacy_record_map m,migration_batch b WHERE o.reminder_id=r.id AND r.contract_id=m.target_id AND m.batch_id=b.id AND b.run_id=:'run' AND m.target_table='hr_contract' AND m.is_active;DELETE FROM hr_contract_reminder_action a USING hr_contract_reminder r,legacy_record_map m,migration_batch b WHERE a.reminder_id=r.id AND r.contract_id=m.target_id AND m.batch_id=b.id AND b.run_id=:'run' AND m.target_table='hr_contract' AND m.is_active;DELETE FROM hr_contract_reminder r USING legacy_record_map m,migration_batch b WHERE r.contract_id=m.target_id AND m.batch_id=b.id AND b.run_id=:'run' AND m.target_table='hr_contract' AND m.is_active;DELETE FROM hr_contract_legacy_evidence e USING legacy_record_map m,migration_batch b WHERE e.contract_id=m.target_id AND m.batch_id=b.id AND b.run_id=:'run' AND m.target_table='hr_contract' AND m.is_active;DELETE FROM hr_contract_change x USING legacy_record_map m,migration_batch b WHERE m.batch_id=b.id AND b.run_id=:'run' AND m.target_table='hr_contract_change' AND m.is_active AND x.id=m.target_id;DELETE FROM hr_contract x USING legacy_record_map m,migration_batch b WHERE m.batch_id=b.id AND b.run_id=:'run' AND m.target_table='hr_contract' AND m.is_active AND x.id=m.target_id;DELETE FROM hr_contract_type x USING legacy_record_map m,migration_batch b WHERE m.batch_id=b.id AND b.run_id=:'run' AND m.target_table='hr_contract_type' AND m.is_active AND x.id=m.target_id;DO $$BEGIN IF EXISTS(SELECT 1 FROM legacy_record_map m JOIN migration_batch b ON b.id=m.batch_id LEFT JOIN hr_contract c ON m.target_table='hr_contract' AND c.id=m.target_id LEFT JOIN hr_contract_change ch ON m.target_table='hr_contract_change' AND ch.id=m.target_id LEFT JOIN hr_contract_type t ON m.target_table='hr_contract_type' AND t.id=m.target_id WHERE b.run_id=current_setting('yz.run') AND m.is_active AND (c.id IS NOT NULL OR ch.id IS NOT NULL OR t.id IS NOT NULL))THEN RAISE EXCEPTION 'T2 rollback residual is not zero';END IF;END$$;UPDATE legacy_record_map SET is_active=false WHERE batch_id=(SELECT id FROM migration_batch WHERE run_id=:'run');UPDATE migration_batch SET status='rolled_back',phase='rollback',finished_at=now(),counts=counts||jsonb_build_object('rollbackResidual',0) WHERE run_id=:'run';COMMIT;
SQL
